#! env python

# 待爬虫的url列表
url_list = [ 
    'http://ziyuan3721.com',
    'https://www.baidu.com',
    'ftp://abc.com'
]

#循环是这样的
for url in url_list:
    #条件判断
    if url.startswith('http:'):
        port = 80
    elif url.startswith('https:'):
        port = 443
    elif url.startswith('ftp:'):
        port = 21

    print("port for {} is: {}".format( url, port ) )

#变量的作用域
print( "Last", url, port )

